                   MAX(CASE WHEN JSON_VALUE(w6.c2, '$.type()') <> 'null' THEN w6.c2 END) KEEP (DENSE_RANK FIRST ORDER BY CASE DECODE(JSON_VALUE(w6.c2, '$.type()'), 'double', 'number', 'float', 'number', JSON_VALUE(w6.c2, '$.type()')) WHEN 'object' THEN CASE CASE WHEN JSON_VALUE(w6.c2, '$.type()') = 'object' THEN JSON_VALUE(w6.c2, '$."$t"') END WHEN 'datetime' THEN 2.1 WHEN 'localdatetime' THEN 2.2 WHEN 'date' THEN 2.3 WHEN 'time' THEN 2.4 WHEN 'localtime' THEN 2.5 WHEN 'duration' THEN 2.6 ELSE 1 END WHEN 'array' THEN 2 WHEN 'string' THEN 3 WHEN 'boolean' THEN 4 WHEN 'number' THEN 5 END DESC NULLS LAST, CASE WHEN NOT NVL(JSON_VALUE(w6.c2, '$.type()'), 'null') = 'null' THEN (SELECT COALESCE(LISTAGG(CASE WHEN NVL(JSON_VALUE(mk1.item, '$.type()'), 'null') = 'null' THEN '~' ELSE JSON_VALUE(mk1.item, '$.s') END ON OVERFLOW TRUNCATE '' WITHOUT COUNT) WITHIN GROUP (ORDER BY mk1.item_no), '') || '!' FROM LATERAL (SELECT /*+ NO_MERGE */ w6.c2 AS list FROM DUAL) mk1_l CROSS JOIN LATERAL (SELECT mk1_r.n AS item_no, JSON_QUERY(mk1_l.list, '$[$i]' PASSING mk1_r.n - 1 AS "i" RETURNING JSON) AS item FROM (SELECT LEVEL n FROM DUAL CONNECT BY LEVEL <= GREATEST(NVL(JSON_VALUE(mk1_l.list, '$.size()' RETURNING NUMBER), 0), 1)) mk1_r WHERE mk1_r.n <= JSON_VALUE(mk1_l.list, '$.size()' RETURNING NUMBER)) mk1) END DESC NULLS LAST) AS c2
