]+)D)?', 1, 1, NULL, 7)), 0) * 7 + COALESCE(TO_NUMBER(REGEXP_SUBSTR(sh15.v2, '^(-?)P((-?[0-9.]+)Y)?((-?[0-9.]+)M)?((-?[0-9.]+)W)?((-?[0-9.]+)D)?', 1, 1, NULL, 9)), 0)))), 'DAY') + NUMTODSINTERVAL(((CASE WHEN SUBSTR(sh15.v2, 1, 1) = '-' THEN -1 WHEN sh15.v2 IS NOT NULL THEN 1 END * (COALESCE(TO_NUMBER(REGEXP_SUBSTR(sh15.v2, 'T((-?[0-9.]+)H)?((-?[0-9.]+)M)?((-?[0-9.]+)S)?$', 1, 1, NULL, 2)), 0) * 3600 + COALESCE(TO_NUMBER(REGEXP_SUBSTR(sh15.v2, 'T((-?[0-9.]+)H)?((-?[0-9.]+)M)?((-?[0-9.]+)S)?$', 1, 1, NULL, 4)), 0) * 60 + COALESCE(TO_NUMBER(REGEXP_SUBSTR(sh15.v2, 'T((-?[0-9.]+)H)?((-?[0-9.]+)M)?((-?[0-9.]+)S)?$', 1, 1, NULL, 6)), 0)))), 'SECOND')) AS v1) sh17) FROM (SELECT /*+ NO_MERGE */ (SELECT CASE WHEN CASE WHEN JSON_VALUE(sh2.v1, '$.type()') = 'object' THEN JSON_VALUE(sh2.v1, '$."$t"') END IS NOT NULL THEN CASE WHEN CASE WHEN JSON_VALUE(sh2.v1, '$.type()') = 'object' THEN JSON_VALUE(sh2.v1, '$."$t"') END = 'datetime' AND SUBSTR(JSON_VALUE(sh2.v1, '$.v'), 1, 1) IN ('1', '2', '3', '4', '5', '6', '7', '8', '9') AND SUBSTR(JSON_VALUE(sh2.v1, '$.v'), 5, 1) = '-' THEN CASE WHEN JSON_VALUE(JSON_SCALAR(REGEXP_REPLACE(JSON_VALUE(sh2.v1, '$.v'), '(Z|[+-][0-9]{2}:?[0-9]{2})$', '')), '$' RETURNING TIMESTAMP) IS NOT NULL THEN to_char(JSON_VALUE(JSON_SCALAR(REGEXP_REPLACE(JSON_VALUE(sh2.v1, '$.v'), '(Z|[+-][0-9]{2}:?[0-9]{2})$', '')), '$' RETURNING TIMESTAMP), 'YYYY-MM-DD"T"') || to_char(JSON_VALUE(JSON_SCALAR(REGEXP_REPLACE(JSON_VALUE(sh2.v1, '$.v'), '(Z|[+-][0-9]{2}:?[0-9]{2})$', '')), '$' RETURNING TIMESTAMP), 'HH24:MI:SS') || CASE WHEN TO_CHAR(JSON_VALUE(JSON_SCALAR(REGEXP_REPLACE(JSON_VALUE(sh2.v1, '$.v'), '(Z|[+-][0-9]{2}:?[0-9]{2})$', '')), '$' RETURNING TIMESTAMP), 'FF6') = '000000' THEN '' WHEN SUBSTR(TO_CHAR(JSON_VALUE(JSON_SCALAR(REGEXP_REPLACE(JSON_VALUE(sh2.v1, '$.v'), '(Z|[+-][0-9]{2}:?[0-9]{2})$', '')), '$' RETURNING TIMESTAMP), 'FF6'), 4, 3) = '000' THEN '.' || SUBSTR(TO_CHAR(JSON_VALUE(JSON_SCALAR(REGEXP_REPLACE(JSON_VALUE(sh2.v1, '$.v'), '(Z|[+-][0-9]{2}:?[0-9